            assert(0 <= pre_r <= pre.rc_width);
            assert(0 <= post_r <= pre.rc_width);  // Since pre_r + 1 <= pre.rc_width

            // Show that the forall condition still holds
            assert forall |x| #[trigger] post.shared_guard.count(x) > 0 ==> !(0 <= x.0 < post_r) by {
                assert(pre.shared_guard.count(x) > 0 ==> !(0 <= x.0 < pre_r));  // By pre invariant
                assert(post.shared_guard == pre.shared_guard);  // The transition doesn't change shared_guard
                assert(!(0 <= x.0 < pre_r));  // By pre invariant and assumption
                assert(!(0 <= x.0 < post_r));  // Since post_r = pre_r + 1 and x.0 is integer
            }
        }
